<template>
  <view class="page-shell profile-page"><view class="panel"><view class="form-row"><text class="form-label">姓名</text><input class="form-input" v-model.trim="form.name" maxlength="20" /></view><view class="form-row"><text class="form-label">手机号</text><input class="form-input" v-model.trim="form.phone" type="number" maxlength="11" /></view><view class="form-row"><text class="form-label">登录账号</text><view class="form-input readonly">{{form.account}}</view></view><button class="primary-btn" :loading="loading" @tap="save">保存</button></view></view>
</template>
<script>import{familyProfile,updateFamilyProfile,setSession,getToken}from'../../api/request';export default{data(){return{form:{account:'',name:'',phone:'',avatar:''},loading:false}},onLoad(){this.load()},methods:{async load(){try{const r=await familyProfile();this.form={...this.form,...r.data}}catch(e){}},async save(){if(!this.form.name||!/^1\d{10}$/.test(this.form.phone))return uni.showToast({title:'请填写正确的姓名和手机号',icon:'none'});this.loading=true;try{await updateFamilyProfile(this.form);setSession({...this.form,token:getToken()});uni.showToast({title:'保存成功',icon:'success'});setTimeout(()=>uni.navigateBack(),400)}catch(e){}finally{this.loading=false}}}}</script>
<style scoped>.profile-page{padding-top:4rpx}.readonly{line-height:84rpx;color:#8f959e}</style>
